import axios from 'axios';

const API_BASE_URL = 'http://localhost:3000/api';

// Children
export const getChildren = async () => {
  const response = await axios.get(`${API_BASE_URL}/children`);
  return response.data;
};

export const getChild = async (id) => {
  const response = await axios.get(`${API_BASE_URL}/children/${id}`);
  return response.data;
};

export const addChild = async (childData) => {
  const response = await axios.post(`${API_BASE_URL}/children`, childData);
  return response.data;
};

export const updateChild = async (id, childData) => {
  const response = await axios.put(`${API_BASE_URL}/children/${id}`, childData);
  return response.data;
};

export const deleteChild = async (id) => {
  const response = await axios.delete(`${API_BASE_URL}/children/${id}`);
  return response.data;
};

// Reports
export const getReports = async () => {
  const response = await axios.get(`${API_BASE_URL}/reports`);
  return response.data;
};

export const getReportsByChild = async (childId) => {
  const response = await axios.get(`${API_BASE_URL}/reports/${childId}`);
  return response.data;
};

export const addReport = async (reportData) => {
  const response = await axios.post(`${API_BASE_URL}/reports`, reportData);
  return response.data;
};

export const deleteReport = async (id) => {
  const response = await axios.delete(`${API_BASE_URL}/reports/${id}`);
  return response.data;
};

// Attendance
export const getAttendance = async () => {
  const response = await axios.get(`${API_BASE_URL}/attendance`);
  return response.data;
};

export const getAttendanceByChild = async (childId) => {
  const response = await axios.get(`${API_BASE_URL}/attendance/child/${childId}`);
  return response.data;
};

export const addAttendance = async (attendanceData) => {
  const response = await axios.post(`${API_BASE_URL}/attendance`, attendanceData);
  return response.data;
};

export const deleteAttendance = async (id) => {
  const response = await axios.delete(`${API_BASE_URL}/attendance/${id}`);
  return response.data;
};
